    {
      "type": "set_spending",
      "target": null,
      "amount": 0.0,
      "sub": "military",
      "regions": [],
      "order": "Maintain robust military expenditure at 36.6 percent of GDP to sustain the war effort."
    },
    {
      "type": "join_organisation",
      "target": null,
      "amount": 0.0,
      "sub": "EU",
      "regions": [],
      "order": "Formally pursue integration and alignment with the European Union."
    },
    {
      "type": "join_organisation",
      "target": null,
      "amount": 0.0,
      "sub": "NATO",
      "regions": [],
      "order": "Pursue formal membership and security guarantees with NATO."
    },
    {
      "type": "aid_request",
      "target": "USA",
      "amount": 5000,
      "sub": "financial and military aid",
      "regions": [],
      "order": "Request vital military and financial assistance from the United States."
    },
    {
      "type": "concessions",
      "target": null,
      "amount": 0.2,
      "sub": "",
      "regions": [],
      "order": "Implement targeted socioeconomic concessions to ease widespread public and worker discontent."
    }
  ],
  "cables": [
    {
      "to": "USA",
      "private": true,
      "text": "We request continued steadfast support, intelligence sharing, and military aid to defend our sovereign territory against ongoing Russian aggression."
    },
    {
      "to": "DEU",
      "private": true,
      "text": "We value our strong trade and political partnership and seek enhanced diplomatic and defensive backing within the European framework."
    },
    {
      "to": "POL",
      "private": true,
      "text": "As a frontline ally, we deeply appreciate your solidarity and wish to further coordinate regional security measures."
    }
  ],
  "public_statement": "The government of Ukraine remains resolute in its defence of our sovereignty, freedom, and territorial integrity. While we face immense challenges from ongoing foreign aggression, we are actively strengthening our democratic institutions, pursuing European integration, and working tirelessly to ensure the welfare and security of all Ukrainian citizens.",
